const days = $json.sinceDays;
const since = new Date(Date.now() - days * 86400000).toISOString();
return [{ json: { period: $json.period, since } }];

const raw = $input.first().json.data ?? $input.first().json.body ?? '';
const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
const rpc = JSON.parse(line.slice(5).trim());
if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? 'workActivity.feed error');
const rows = JSON.parse(rpc.result?.content?.[0]?.text ?? '[]');
const period = $('Compute since').first().json.period;
if (!Array.isArray(rows) || rows.length === 0) return []; // nothing to digest -> stop

const personGroups = {};
const projectGroups = {};
for (const r of rows) {
  if (r.actorUserId) (personGroups[r.actorUserId] = personGroups[r.actorUserId] || []).push(r);
  const links = Array.isArray(r.links) ? r.links : [];
  for (const l of links) {
    if (l.targetKind === 'project') (projectGroups[l.targetId] = projectGroups[l.targetId] || []).push(r);
  }
}
const items = [];
for (const [id, activities] of Object.entries(personGroups)) items.push({ kind: 'person', id, activities, period });
for (const [id, activities] of Object.entries(projectGroups)) items.push({ kind: 'project', id, activities, period });
return items.map((it) => ({ json: it }));

// NOTE: '.item' (pairedItem-resolved), NOT '.first()' -- 'Is project?' fans out into two
// branches that reconverge later, so 'Build summary text' below runs ONCE PER BRANCH (a separate
// run per branch, not one batched call). '.first()' blindly grabs run-index 0 regardless of which
// branch produced the item currently in flight, which is wrong whenever the other branch's run
// happens to be recorded first (found live: it crashed downstream when the project branch's
// zero-item run landed at index 0). '.item' follows the actual pairedItem lineage of THIS item.
const prev = $('Is project?').item.json;
let project = {};
try {
  const raw = $input.first().json.data ?? $input.first().json.body ?? '';
  const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
  const rpc = JSON.parse(line.slice(5).trim());
  if (!rpc.result?.isError) project = JSON.parse(rpc.result?.content?.[0]?.text ?? '{}');
} catch { project = {}; }
const recipientId = project.owner?.responsibleId ?? null;
const label = project.name ?? prev.id;
return [{ json: { ...prev, recipientId, label } }];

const it = $json;
if (!it.recipientId) return []; // e.g. a project with no owner set -- no one to notify
const lines = (it.activities || []).map((a) => `- [${a.source}] ${a.verb} ${a.objectKind}${a.title ? `: ${a.title}` : ''} (${a.occurredAt})`);
const text = `${it.kind === 'project' ? 'Project' : 'Person'} activity digest (${it.period}) for ${it.label} — ${it.activities.length} item(s):\n${lines.join('\n')}`;
return [{ json: { kind: it.kind, id: it.id, period: it.period, recipientId: it.recipientId, label: it.label, count: it.activities.length, text } }];

// '.item' not '.first()' -- same multi-run fan-in reason as 'Parse owner (may be null)' above.
const raw = $input.first().json.data ?? $input.first().json.body ?? '';
const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
const rpc = JSON.parse(line.slice(5).trim());
if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? 'llm.summarize error');
const summary = rpc.result?.content?.[0]?.text ?? '';
const prev = $('Build summary text (skip if no recipient)').item.json;
return [{ json: { ...prev, summary } }];

const raw = $input.first().json.data ?? $input.first().json.body ?? '';
const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
const rpc = JSON.parse(line.slice(5).trim());
if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? 'notify failed');
return [{ json: { ok: true } }];

const raw = $input.first().json.data ?? $input.first().json.body ?? '';
const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
const rpc = JSON.parse(line.slice(5).trim());
if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? 'workActivity.relink failed');
const result = JSON.parse(rpc.result?.content?.[0]?.text ?? '{}');
return [{ json: result }];
